func encode(t *testing.T, f fixture) []byte {
	t.Helper()
	act := filedef.NewActivity()
	act.FileId.
		SetType(f.fileType).
		SetManufacturer(typedef.ManufacturerGarmin).
		SetProduct(4440).
		SetSerialNumber(f.serial).
		SetTimeCreated(f.created)

	start := f.created.Add(time.Minute)
	for i := range f.points {
		rec := mesgdef.NewRecord(nil).
			SetTimestamp(start.Add(time.Duration(i) * time.Second)).
			SetDistance(uint32(i * 800)). // 8 m/s, scale 100
			SetHeartRate(120 + f.hrOffset).
			SetCadence(85).
			SetEnhancedAltitude(uint32((400 + 500) * 5)) // 400 m, scale 5, offset 500
		if f.withGPS {
			rec.SetPositionLat(semicircles.ToSemicircles(48.2 + float64(i)*1e-4)).
				SetPositionLong(semicircles.ToSemicircles(12.8))
		}
		if f.power {
			rec.SetPower(210)
		}
		act.Records = append(act.Records, rec)
	}
	end := start.Add(time.Duration(f.points) * time.Second)
	if f.noSession {
		fit := act.ToFIT(nil)
		var buf bytes.Buffer
		if err := encoder.New(&buf).Encode(&fit); err != nil {
			t.Fatalf("encode fixture: %v", err)
		}
		return buf.Bytes()
	}
	act.Laps = append(act.Laps, mesgdef.NewLap(nil).SetTimestamp(end).SetStartTime(start))
	act.Sessions = append(act.Sessions, mesgdef.NewSession(nil).
		SetTimestamp(end).
		SetStartTime(start).
		SetSport(typedef.SportCycling).
		SetSubSport(typedef.SubSportRoad).
		SetTotalDistance(uint32(f.points*800)).
		SetTotalTimerTime(uint32(f.points*1000)).
		SetTotalElapsedTime(uint32(f.points*1000)).
		SetTotalAscent(12))
	act.Activity = mesgdef.NewActivity(nil).SetTimestamp(end).SetNumSessions(1).SetType(typedef.ActivityManual)

	fit := act.ToFIT(nil)
	var buf bytes.Buffer
	if err := encoder.New(&buf).Encode(&fit); err != nil {
		t.Fatalf("encode fixture: %v", err)
	}
	return buf.Bytes()
}

func TestParseSummary(t *testing.T) {
	s, err := Parse(bytes.NewReader(encode(t, defaultFixture())))
	if err != nil {
		t.Fatal(err)
	}
	if s.Key != "fit:1:3412345678:1777622400" || s.KeySource != "file_id" {
		t.Errorf("key = %q (%s)", s.Key, s.KeySource)
	}
	if s.Manufacturer != "garmin" || s.Sport != "cycling" || s.SubSport != "road" {
		t.Errorf("unexpected device/sport: %+v", s)
	}
	if s.DistanceM != 480 || s.TimerS != 60 || s.AscentM != 12 || s.Sessions != 1 {
		t.Errorf("unexpected totals: distance=%v timer=%v ascent=%v sessions=%d", s.DistanceM, s.TimerS, s.AscentM, s.Sessions)
	}
	if s.Records != 60 || s.GPSPoints != 60 || !s.HasHR || !s.HasPower || !s.HasCadence || !s.HasAltitude {
		t.Errorf("unexpected record stats: %+v", s)
	}
	if !s.StartTime.Equal(created.Add(time.Minute)) {
		t.Errorf("start time = %v", s.StartTime)
	}
}

func TestKeyIsStableAcrossContentChanges(t *testing.T) {
	// Same recording (file_id) with different content, e.g. a re-saved file:
	// the key must match so that re-imports update instead of duplicating.
	a := defaultFixture()
	b := defaultFixture()
	b.hrOffset = 5

	sa, err := Parse(bytes.NewReader(encode(t, a)))
	if err != nil {
		t.Fatal(err)
	}
	sb, err := Parse(bytes.NewReader(encode(t, b)))
	if err != nil {
		t.Fatal(err)
	}
	if sa.Key != sb.Key {
		t.Errorf("keys differ: %s vs %s", sa.Key, sb.Key)
	}
	if sa.SHA256 == sb.SHA256 {
		t.Error("content hashes must differ")
	}
}

func TestKeyDistinguishesDevices(t *testing.T) {
	// fēnix and Edge recording the same ride in parallel: same time, different serials.
	a := defaultFixture()
	b := defaultFixture()
	b.serial = 3499999999

	sa, _ := Parse(bytes.NewReader(encode(t, a)))
	sb, _ := Parse(bytes.NewReader(encode(t, b)))
	if sa.Key == sb.Key {
		t.Error("parallel recordings of two devices must have distinct keys")
	}
}

